// Generated by crates/xtask from the Rust question model.
// Do not edit by hand; run ./build.sh (or cargo run -p xtask -- tsgen).

import type { ChoiceOption } from "./ChoiceOption";
import type { NumericTolerance } from "./NumericTolerance";
import type { SelectionCardinality } from "./SelectionCardinality";
import type { TextMatchMode } from "./TextMatchMode";

/**
 * The shape of response a question expects.
 *
 * Every variant carries the information a widget needs to render an input and
 * validate its shape locally. None of it reveals a correct answer.
 */
export type ResponseDefinition =
  | {
      kind: "numeric";
      tolerance: NumericTolerance;
      unit: string | null;
    }
  | {
      kind: "multipleChoice";
      choices: Array<ChoiceOption>;
      selection: SelectionCardinality;
    }
  | {
      kind: "shortText";
      matchMode: TextMatchMode;
      maxLength: number;
    }
  | {
      kind: "ordering";
      items: Array<ChoiceOption>;
    }
  | {
      kind: "fileUpload";
      maxBytes: number;
      acceptedExtensions: Array<string>;
    };
